# The reference values of the Python package's parity tests: every
# exported function on a set of inputs, and the messages of bad calls, as
# the installed R package gives them. From the package root:
#   Rscript dev/pyref.R [LIB]
# writes py/tests/data/ref.json; LIB is a library holding crimlab. The file
# is regenerated by this script only, never edited by hand.
#
# JSON is written here without a dependency: a vector is
# {"<type>": [values], "names": [names] or null}, type num, int, chr or
# lgl; doubles have 17 significant digits (exact), NaN and infinities are
# strings, NA is null. A matrix is {"mat": {"dim", "v" (column by
# column), "rn", "cn"}}, a data frame {"df": {column: vector}, "rn"}, a list
# {"list": {name: value}}.
a <- commandArgs(TRUE)
if (length(a)) .libPaths(c(a[1L], .libPaths()))
suppressPackageStartupMessages(library(crimlab))
grDevices::pdf(NULL)

esc <- function(s) {
  if (!length(s)) return(character(0))
  paste0('"', gsub('"', '\\\\"', gsub("\\\\", "\\\\\\\\", enc2utf8(s))), '"')
}
one <- function(v) {
  if (is.character(v)) return(if (is.na(v)) "null" else esc(v))
  if (is.logical(v)) return(if (is.na(v)) "null" else if (v) "true" else "false")
  if (is.integer(v)) return(if (is.na(v)) "null" else sprintf("%d", v))
  if (is.nan(v)) return('"NaN"')
  if (is.na(v)) return("null")
  if (is.infinite(v)) return(if (v > 0) '"Inf"' else '"-Inf"')
  sprintf("%.17g", v)
}
vec <- function(x) paste0("[", paste(vapply(x, one, ""), collapse = ","), "]")
obj <- function(l) {
  paste0("{", paste(sprintf("%s:%s", esc(names(l)), vapply(l, js, "")),
                    collapse = ","), "}")
}
js <- function(x) {
  if (is.null(x)) return("null")
  if (is.data.frame(x)) {
    rn <- if (.row_names_info(x) > 0L) vec(rownames(x)) else "null"
    return(sprintf('{"df":%s,"rn":%s}', obj(as.list(x)), rn))
  }
  if (is.list(x)) return(sprintf('{"list":%s}', obj(x)))
  if (is.matrix(x)) {
    rn <- rownames(x)
    cn <- colnames(x)
    return(sprintf('{"mat":{"dim":%s,"v":%s,"rn":%s,"cn":%s}}', vec(dim(x)),
                   vec(as.vector(x)), if (is.null(rn)) "null" else vec(rn),
                   if (is.null(cn)) "null" else vec(cn)))
  }
  ty <- switch(typeof(x), double = "num", integer = "int", character = "chr",
               logical = "lgl", stop("cannot write a ", typeof(x)))
  nm <- names(x)
  sprintf('{"%s":%s,"names":%s}', ty, vec(unname(x)),
          if (is.null(nm)) "null" else vec(nm))
}

cases <- character(0)
# ok(): a call and its result; bad(): a call and the message it stops with
add <- function(fn, args, key, val) {
  cases[length(cases) + 1L] <<- sprintf('{"fn":%s,"args":%s,"%s":%s}',
                                        esc(fn), obj(args), key, val)
}
# (.f, not fn: proof() has an argument fn)
ok <- function(.f, ...) {
  args <- list(...)
  add(.f, args, "out", js(do.call(.f, args)))
}
bad <- function(.f, ...) {
  args <- list(...)
  m <- tryCatch({
    do.call(.f, args)
    NULL
  }, error = conditionMessage)
  if (is.null(m)) stop("no error from ", .f, call. = FALSE)
  add(.f, args, "err", esc(m))
}

